    for rid, st, ag, dj in zip(events['run_id'].values, events['step'].values, events['agent_id'].values, events['decision_json'].values):
        try:
            d = json.loads(dj) if isinstance(dj, str) else None
        except Exception:
            d = None
        ed = d.get('escape_direction') if isinstance(d, dict) else None
        if isinstance(ed, list) and len(ed) == 2:
            try:
                esc_rows.append({'run_id': rid, 'step': int(st), 'agent_id': int(ag), 'ex': float(ed[0]), 'ey': float(ed[1])})
            except Exception:
                pass
    esc = pd.DataFrame(esc_rows, columns=['run_id', 'step', 'agent_id', 'ex', 'ey'])
    rows = []
    for (rid, st), grp in contacts.groupby(['run_id', 'step'], observed=True):
        adj = defaultdict(set)
        for a, b in zip(grp['agent_id'].values, grp['partner_id'].values):
            if pd.isna(a) or pd.isna(b):
                continue
            ai = int(a); bi = int(b)
            if ai == bi:
                continue
            adj[ai].add(bi); adj[bi].add(ai)
        seen = set(); cid = 0
        for node in list(adj.keys()):
            if node in seen:
                continue
            stack = [node]; comp = []
            while stack:
                cur = stack.pop()
                if cur in seen:
                    continue
                seen.add(cur); comp.append(cur)
                for nb in adj[cur]:
                    if nb not in seen:
                        stack.append(nb)
            for m in comp:
                rows.append({'run_id': rid, 'step': int(st), 'group_id': int(cid), 'agent_id': int(m)})
            cid += 1
    if not rows:
        return pd.Series(dtype=float, index=pd.MultiIndex.from_arrays([[], []], names=['step', 'group_id']))
    comp_df = pd.DataFrame(rows)
    merged = comp_df.merge(fish, on=['run_id', 'step', 'agent_id'], how='inner')
    if esc.shape[0] > 0:
        merged = merged.merge(esc, on=['run_id', 'step', 'agent_id'], how='left')
    else:
        merged['ex'] = np.nan; merged['ey'] = np.nan
    if merged.shape[0] == 0:
        return pd.Series(dtype=float, index=pd.MultiIndex.from_arrays([[], []], names=['step', 'group_id']))
